const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search across all tables for this ID
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  for (const c of cols) {
    try {
      const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE ' + c.name + ' LIKE ?').all('%PROD-B98D14%');
      if (rows.length > 0) {
        console.log('Found in table:', t.name, 'column:', c.name);
        console.log(JSON.stringify(rows, null, 2));
      }
    } catch(e) {}
  }
}
db.close();
"

